set feedback on echo on pagesize 100 linesize 160
whenever sqlerror continue
col sequence_owner format a12
col sequence_name format a32
SELECT SEQUENCE_OWNER, SEQUENCE_NAME FROM ALL_SEQUENCES ORDER BY 1, 2;
SELECT PRIVILEGE FROM USER_SYS_PRIVS ORDER BY 1;
SET TRANSACTION READ ONLY;
SELECT APP_OWNER.NEXT_ID() FROM DUAL;
SELECT APP_OWNER.NEXT_ID() FROM DUAL;
SELECT APP_OWNER.BUMP() FROM DUAL;
